    fn dialog_image(&self, name: &str) -> Option<ImageData> {
        self.startup_dialog_images.get(name).cloned()
    }

    fn loader_resources(&self) -> Result<LoaderResources> {
        let fonts = self
            .clonk_fonts
            .clone()
            .context("CStdFont-faithful loader fonts are unavailable")?;
        let progress = self
            .dialog_image("GUIProgress.png")
            .context("GUIProgress.png is unavailable")?;
        LoaderResources::new(fonts, progress)
    }

    fn context_menu_resources(
        &self,
    ) -> Result<lc_frontend::context_menu::ContextMenuResources> {
        let fonts = self
            .clonk_fonts
            .as_deref()
            .context("CStdFont-faithful GUI fonts are unavailable")?;
        let tooltip_fonts = self
            .plrsel_book_fonts
            .as_deref()
            .context("shadowless classic tooltip font is unavailable")?;
        let icons = self
            .startup_dialog_images
            .get("GUIIcons.png")
            .context("GUIIcons.png is unavailable")?;
        let submenu_arrow = self
            .startup_dialog_images
            .get("GUISubmenu.png")
            .context("GUISubmenu.png is unavailable")?;
        lc_frontend::context_menu::ContextMenuResources::new(
            &fonts.text,
            &tooltip_fonts.text,
            icons,
            submenu_arrow,
        )
    }

    fn game_over_classic_resources(&self) -> Option<GameOverClassicResources<'_>> {
        let caption = self.startup_dialog_images.get("GUICaption.png")?;
        let button = self.startup_dialog_images.get("GUIButton.png")?;
        let button_down = self.startup_dialog_images.get("GUIButtonDown.png")?;
        let button_highlight = self.game_over_button_highlight.as_ref()?;
        let fonts = self.clonk_fonts.as_deref()?;
        Some(GameOverClassicResources::new(
            lc_frontend::classic_gui::ClassicGuiSkin::new(
                caption,
                button,
                button_down,
                Some(button_highlight),
            ),
            fonts,
            Some(button_highlight),
            self.startup_dialog_images.get("GUIIcons.png"),
            self.startup_dialog_images.get("Player.png"),
            self.hud_graphics.score.as_ref(),
        ))
    }

