impl fmt::Display for ClassicParityBoundary {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::StartupBootstrapResources { issues } => write!(
                f,
                "classic startup bootstrap is unavailable ({}); refusing every startup root before cache or pixels",
                issues
                    .iter()
                    .map(ToString::to_string)
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
            Self::StartupSubscreen(subscreen) => write!(
                f,
                "classic startup subscreen {subscreen:?} is not implemented; refusing incomplete Rust pane"
            ),
            Self::StartupAction(action) => write!(
                f,
                "classic startup action {action:?} is not implemented; refusing generic status or side effect"
            ),
            Self::StartupModel { view, missing } => write!(
                f,
                "classic startup model {missing} is unavailable for {view:?}; refusing generic Rust fallback"
            ),
            Self::StartupStatusOverlay { view, status } => write!(
                f,
                "classic startup status presentation is unavailable in {view:?}: {status}; refusing generic Rust status overlay"
            ),
            Self::StartupGameOver { view } => write!(
                f,
                "classic game-over evaluation dialog is running-mode only, but stale state reached startup view {view:?}; refusing a startup overlay or silent omission"
            ),
            Self::StartupScreen { view } => write!(
                f,
                "classic startup screen {view:?} is unavailable; refusing generic Rust fallback"
            ),
            Self::StartupMainResources { missing } => write!(
                f,
                "classic startup main-menu resources are unavailable (missing {})",
                missing.join(", ")
            ),
            Self::FolderMap { identifier, marker } => write!(
                f,
                "scenario folder `{identifier}` uses unported FolderMap layout at {}",
                marker.display()
            ),
            Self::FolderMapInspection { path, detail } => write!(
                f,
                "cannot verify classic FolderMap layout for {}: {detail}",
                path.display()
            ),
            Self::EditorScenario { identifier } => write!(
                f,
                "classic editor entry `{identifier}` is unavailable in the Rust menu"
            ),
            Self::EditScenario { identifier } => write!(
                f,
                "classic Edit action for `{identifier}` is unavailable in the Rust menu"
            ),
            Self::ScenarioSelectorShortcut { key, action } => write!(
                f,
                "classic scenario-selector {action} action ({key}) is unavailable; refusing conflicting Rust fallback"
            ),
            Self::IngameMenuResources { missing } => write!(
                f,
                "classic in-game menu resources are unavailable (missing {})",
                missing.join(", ")
            ),
            Self::GameOverResources { missing } => write!(
                f,
                "classic game-over resources are unavailable (missing {}); refusing generic Rust fallback",
                missing.join(", ")
            ),
            Self::ScriptMenuPointerResources { detail } => write!(
                f,
                "classic script-menu pointer resources are unavailable: {detail}; refusing world-pointer fallthrough"
            ),
            Self::IngameMenuChild(child) => write!(
                f,
                "classic in-game menu child {child:?} is not implemented; refusing status/no-op substitute"
            ),
            Self::ObjectMenu(kind) => write!(
                f,
                "classic object menu {kind:?} is not implemented; refusing generic Rust object menu"
            ),
            Self::GameOverChat(mode) => write!(
                f,
                "classic game-over {mode:?} C4MessageInput is unavailable; refusing evaluation-button activation"
            ),
            Self::GameOverFocusTraversal(direction) => write!(
                f,
                "classic game-over {direction:?} focus traversal is unavailable; refusing guessed button focus"
            ),
            Self::GameOverMnemonic(mask) => write!(
                f,
                "classic game-over {mask:?} localized mnemonic dispatch is unavailable; refusing guessed button or global-key action"
            ),
            Self::RuntimeHelpToggle => write!(
                f,
                "classic runtime F1 help overlay is unavailable; refusing generic Rust help pane"
            ),
            Self::RuntimeClientListToggle(role) => write!(
                f,
                "classic runtime C4Network2ClientListDlg toggle is unavailable for {role:?} network role; refusing generic client pane"
            ),
            Self::RuntimePause(RuntimePauseBoundary::OfflineHaltCountUnavailable) => write!(
                f,
                "classic offline Pause toggle is unavailable because Game.HaltCount ownership is not modeled"
            ),
            Self::RuntimePause(RuntimePauseBoundary::NetworkHostLeagueUnknown) => write!(
                f,
                "classic network-host Pause route is unavailable because runtime league state is unknown; refusing to guess between vote and host status mutation"
            ),
            Self::RuntimePause(RuntimePauseBoundary::NetworkClientLeagueUnknown) => write!(
                f,
                "classic network-client Pause route is unavailable because runtime league state is unknown; refusing to guess between vote and client no-op"
            ),
            Self::RuntimePause(RuntimePauseBoundary::NetworkRoleUnknown) => write!(
                f,
                "classic network Pause route is unavailable because the runtime network role is ambiguous"
            ),
            Self::Scoreboard {
                trigger,
                rows,
                columns,
                show_count,
            } => write!(
                f,
                "classic C4ScoreboardDlg is unavailable for {trigger:?} (rows={rows}, columns={columns}, show_count={show_count}); refusing a generic Rust scoreboard"
            ),
            Self::RunningViewport(ClassicViewportBoundary::ZeroObjects) => write!(
                f,
                "classic object-independent viewport camera is unavailable for a zero-object world; refusing both the solid navy empty-state fallback and an arbitrary first-object focus/selection"
            ),
            Self::RunningViewport(ClassicViewportBoundary::LocalViewportUnavailable {
                owner,
            }) => write!(
                f,
                "declared local player {owner} has no authoritative local viewport; refusing the solid navy fallback and an arbitrary first-object focus/selection"
            ),
            Self::RunningViewport(ClassicViewportBoundary::LocalFocusUnavailable {
                owner,
                slot,
            }) => write!(
                f,
                "declared local player {owner} viewport slot {slot} has no live focus, cursor, or crew object; refusing the solid navy fallback and an arbitrary first-object focus/selection"
            ),
            Self::RunningViewport(ClassicViewportBoundary::ObserverCameraUnavailable {
                declared_local_players,
            }) => write!(
                f,
                "classic object-independent NO_OWNER observer camera is unavailable for declared local players {declared_local_players:?}; refusing the solid navy fallback and an arbitrary first-object focus/selection"
            ),
            Self::AbortDialog => write!(
                f,
                "classic C4AbortGameDialog is unavailable; refusing menu-shaped approximation"
            ),
            Self::HudGameMessage { count } => write!(
                f,
                "classic C4GameMessage renderer is unavailable for {count} visible message(s)"
            ),
            Self::HudMessageVisibilityUnavailable { count } => write!(
                f,
                "C4GameMessage visibility/FoW state is unavailable for {count} potentially visible target message(s)"
            ),
            Self::RunningShortcut { key } => write!(
                f,
                "running shortcut {key} has no classic renderer/action in the Rust port"
            ),
            Self::LoaderScreen { context, detail } => write!(
                f,
                "classic C4LoaderScreen is unavailable during {context}: {detail}; refusing generic loading approximation"
            ),
            Self::GameLobby(ClassicGameLobbyBoundary::Resources { detail }) => write!(
                f,
                "classic game-lobby resources are unavailable: {detail}; refusing generic lobby"
            ),
            Self::GameLobby(ClassicGameLobbyBoundary::Model { detail }) => write!(
                f,
                "classic game-lobby model is unavailable: {detail}; refusing guessed lobby state"
            ),
            Self::GameLobby(ClassicGameLobbyBoundary::Child(child)) => write!(
                f,
                "classic game-lobby child {child:?} is not implemented; refusing generic child pane"
            ),
        }
    }
}

