fn frame_interval_for_mode(mode: AppMode) -> Duration {
    match mode {
        AppMode::Running => INGAME_FRAME_INTERVAL,
        AppMode::Menu | AppMode::Loading => STARTUP_FRAME_INTERVAL,
    }
}

fn synchronize_frame_interval(
    mode: AppMode,
    frame_interval: &mut Duration,
    accumulator: &mut Duration,
) -> bool {
    let next_interval = frame_interval_for_mode(mode);
    if next_interval == *frame_interval {
        return false;
    }
    *frame_interval = next_interval;
    *accumulator = Duration::ZERO;
    true
}

fn accumulate_frame_time_for_mode(
    mode: AppMode,
    frame_interval: &mut Duration,
    accumulator: &mut Duration,
    elapsed: Duration,
) {
    let clamped = elapsed.min(MAX_ACCUMULATED_TIME);
    *accumulator = (*accumulator + clamped).min(MAX_ACCUMULATED_TIME);
    synchronize_frame_interval(mode, frame_interval, accumulator);
}

struct MenuState {
    menu: StartupMenu,
    pointer_position: Option<GuiPoint>,
    stack: Vec<MenuLayer>,
    /// Entries from the current layer that survive the submitted search.
    /// C++ keeps the loader tree intact and rebuilds only the visible list
    /// (`C4StartupScenSelDlg::UpdateList`, cpp:1472-1538).
    visible_entries: Vec<FrontendScenario>,
    /// Current edit buffer/caret/selection. C++ does not filter until Enter
    /// invokes `OnSearchBarEnter`.
    search_edit: SearchEditState,
    /// Last submitted edit buffer used by `visible_entries`.
    applied_search_text: String,
    /// Logical-pixel offset of the left scenario `C4GUI::ListBox`.
    scenario_list_scroll: i32,
    /// Selection last passed through `ScrollRangeInView`. Keeping this
    /// separate prevents a later render from undoing deliberate wheel/thumb
    /// scrolling when the selection itself did not change.
    list_scroll_selection: Option<Option<usize>>,
    /// Logical-pixel offset of the right-page `C4GUI::TextWindow`.
    selection_info_scroll: i32,
    /// Captured classic scrollbar interaction. C++ retains the pin position
    /// while an arrow is held so one-pixel steps cannot stall on integer
    /// offset rounding (C4GuiContainers.cpp:391-473).
    scrollbar_interaction: Option<ScenselScrollbarInteraction>,
    /// Mutable state of the selection-dependent "Choose definitions"
    /// checkbox. C++ resets these flags from C4S only when selection changes;
    /// canceling the child selector retains a user toggle.
    definition_checkbox_enabled: bool,
    definition_checkbox_checked: bool,
    definition_checkbox_focused: bool,
    /// Recursive C4GUI dialog focus outside the embedded game-option window.
    /// The option controller owns the individual icon focus while this is
    /// `Options`; disabled icon buttons remain traversable like C++ buttons.
    dialog_focus: ScenselDialogFocus,
    /// Whether a synthetic "Back" row is injected at index 0. The network
    /// lobby's generic list uses it; the C++-faithful scenario book does not
    /// (C4StartupScenSelDlg has a Back *button*, no Back list entry).
    include_back: bool,
}

/// `C4GUI::Dialog::AdvanceFocus` order for C4StartupScenSelDlg. The option
/// strip is one recursive child here and owns its constructor-ordered icons.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ScenselDialogFocus {
    Search,
    List,
    Back,
    Definitions,
    Options,
    Open,
}

const SCENSEL_SCROLLBAR_PART: i32 = 16;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ScenselScrollbarTarget {
    List,
    Description,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ScenselScrollbarInteractionKind {
    Dragging,
    Arrow(i32),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ScenselScrollbarInteraction {
    target: ScenselScrollbarTarget,
    kind: ScenselScrollbarInteractionKind,
    pin: i32,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ScenselScrollbarSpec {
    target: ScenselScrollbarTarget,
    rect: lc_frontend::classic_gui::IntRect,
    max_scroll: i32,
    offset: i32,
}

fn scensel_scrollbar_pin_travel(bar_height: i32) -> Option<i32> {
    (bar_height > 3 * SCENSEL_SCROLLBAR_PART)
        .then_some(bar_height - 3 * SCENSEL_SCROLLBAR_PART)
}

fn scensel_scrollbar_pin_from_offset(
    offset: i32,
    max_scroll: i32,
    bar_height: i32,
) -> Option<i32> {
    let travel = scensel_scrollbar_pin_travel(bar_height)?;
    (max_scroll > 0).then(|| {
        let offset = offset.clamp(0, max_scroll);
        i32::try_from(i64::from(travel) * i64::from(offset) / i64::from(max_scroll))
            .unwrap_or(travel)
    })
}

fn scensel_scrollbar_offset_from_pin(
    pin: i32,
    max_scroll: i32,
    bar_height: i32,
) -> Option<i32> {
    let travel = scensel_scrollbar_pin_travel(bar_height)?;
    (max_scroll > 0).then(|| {
        let pin = pin.clamp(0, travel);
        i32::try_from(i64::from(max_scroll) * i64::from(pin) / i64::from(travel))
            .unwrap_or(max_scroll)
    })
}

fn scensel_scrollbar_jump_pin(pointer_y: i32, bar_height: i32) -> Option<i32> {
    let travel = scensel_scrollbar_pin_travel(bar_height)?;
    Some(
        (pointer_y - SCENSEL_SCROLLBAR_PART - SCENSEL_SCROLLBAR_PART / 2)
            .clamp(0, travel),
    )
}

#[derive(Clone, Debug)]
struct MenuLayer {
    title: String,
    entries: Vec<FrontendScenario>,
    /// The folder entry this layer lists the children of (None at root);
    /// shown on the right page when nothing is selected
    /// (C4StartupScenSelDlg::UpdateSelection, cpp:1566-1572).
    folder: Option<FrontendScenario>,
}

struct MainMenuState {
    menu: StartupMainMenu,
    participants_label: String,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum StartupView {
    MainMenu,
    ScenarioBrowser,
    NetworkLobby,
    /// C4StartupNetDlg — the network game browser ("Start Network Game").
    NetworkGame,
    Options,
    About,
    /// C4StartupPlrSelDlg — the player selection dialog.
    PlayerSelection,
}

#[cfg(test)]
impl StartupView {
    const ALL: [Self; 7] = [
        Self::MainMenu,
        Self::ScenarioBrowser,
        Self::NetworkLobby,
        Self::NetworkGame,
        Self::Options,
        Self::About,
        Self::PlayerSelection,
    ];
}

#[derive(Clone, Copy, Debug)]
struct IngameMouseState {
    start: ViewportPointer,
    last: ViewportPointer,
    moved: bool,
}

#[derive(Clone, Debug)]
struct LobbyParticipantState {
    name: String,
    ready: bool,
    #[allow(dead_code)]
    kind: ParticipantKind,
}

impl LobbyParticipantState {
    fn new(name: impl Into<String>, kind: ParticipantKind) -> Self {
        let ready = matches!(kind, ParticipantKind::Observer);
        Self {
            name: name.into(),
            ready,
            kind,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LobbyPointerRegion {
    Menu,
    Panel,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LobbyButton {
    Ready,
    Start,
}

#[derive(Clone, Debug)]
struct NetworkLobbyLayout {
    panel: GuiRect,
    ready_button: GuiRect,
    start_button: Option<GuiRect>,
    menu_region_max_x: f32,
    scenario_rect: GuiRect,
    participants_rect: GuiRect,
}

#[derive(Clone, Debug)]
struct NetworkLobbyState {
    participants: BTreeMap<ClientId, LobbyParticipantState>,
    local_client_id: ClientId,
    is_host: bool,
    selected_identifier: Option<String>,
    selected_title: Option<String>,
    hover_button: Option<LobbyButton>,
    pressed_button: Option<LobbyButton>,
    layout: Option<NetworkLobbyLayout>,
    pointer: Option<GuiPoint>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum LobbyAction {
    ToggleReady,
    StartGame,
}

impl NetworkLobbyState {
    fn new(local_client_id: ClientId, local_name: String, is_host: bool) -> Self {
        let mut participants = BTreeMap::new();
        participants.insert(
            local_client_id,
            LobbyParticipantState::new(local_name, ParticipantKind::Player),
        );
        if !is_host && local_client_id != 0 {
            participants
                .entry(0)
                .or_insert_with(|| LobbyParticipantState::new("Host", ParticipantKind::Player));
        }
        Self {
            participants,
            local_client_id,
            is_host,
            selected_identifier: None,
            selected_title: None,
            hover_button: None,
            pressed_button: None,
            layout: None,
            pointer: None,
        }
    }

    fn scenario_label(&self) -> String {
        self.selected_title
            .clone()
            .unwrap_or_else(|| "Select a scenario from the list".to_string())
    }

    fn selected_identifier(&self) -> Option<&str> {
        self.selected_identifier.as_deref()
    }

    fn select_scenario(&mut self, identifier: &str, title: &str) {
        self.selected_identifier = Some(identifier.to_string());
        self.selected_title = Some(title.to_string());
    }

    fn update_layout(&mut self, width: f32, height: f32) -> &NetworkLobbyLayout {
        let panel_margin = 24.0;
        let min_menu_width = 240.0;
        let mut panel_width = (width * 0.4).clamp(240.0, 420.0);
        if width - panel_width - panel_margin < min_menu_width {
            panel_width = (width - min_menu_width - panel_margin).max(220.0);
        }
        panel_width = panel_width.clamp(220.0, width - panel_margin * 2.0);
        let mut panel_left = width - panel_width - panel_margin;
        if panel_left < panel_margin {
            panel_left = panel_margin;
        }
        let panel_height = (height - panel_margin * 2.0).max(220.0);
        let panel_rect = GuiRect::new(panel_left, panel_margin, panel_width, panel_height);
        let menu_region_max_x = (panel_left - 12.0).max(0.0);

        let scenario_rect = GuiRect::new(
            panel_left + 18.0,
            panel_rect.origin.y + 60.0,
            panel_width - 36.0,
            46.0,
        );

        let button_height = 46.0;
        let button_y = panel_rect.origin.y + panel_rect.size.height - button_height - 24.0;
        let ready_button;
        let start_button;
        if self.is_host {
            let total_width = panel_width - 48.0;
            let button_width = (total_width - 12.0) * 0.5;
            ready_button = GuiRect::new(panel_left + 24.0, button_y, button_width, button_height);
            start_button = Some(GuiRect::new(
                ready_button.origin.x + button_width + 12.0,
                button_y,
                button_width,
                button_height,
            ));
        } else {
            ready_button = GuiRect::new(
                panel_left + 24.0,
                button_y,
                panel_width - 48.0,
                button_height,
            );
            start_button = None;
        }

        let participants_top = scenario_rect.origin.y + scenario_rect.size.height + 18.0;
        let participants_height = (button_y - participants_top - 16.0).max(80.0);
        let participants_rect = GuiRect::new(
            panel_left + 18.0,
            participants_top,
            panel_width - 36.0,
            participants_height,
        );

        self.layout = Some(NetworkLobbyLayout {
            panel: panel_rect,
            ready_button,
            start_button,
            menu_region_max_x,
            scenario_rect,
            participants_rect,
        });
        self.layout.as_ref().expect("layout just initialised")
    }

    fn layout(&mut self, width: f32, height: f32) -> &NetworkLobbyLayout {
        if self.layout.is_none() {
            self.update_layout(width, height);
        }
        self.layout
            .as_ref()
            .expect("network lobby layout should exist")
    }

    fn pointer_region(&self, point: GuiPoint) -> LobbyPointerRegion {
        if let Some(layout) = self.layout.as_ref() {
            if point.x <= layout.menu_region_max_x {
                LobbyPointerRegion::Menu
            } else {
                LobbyPointerRegion::Panel
            }
        } else {
            LobbyPointerRegion::Menu
        }
    }

    fn handle_panel_pointer_move(&mut self, point: GuiPoint) {
        self.pointer = Some(point);
        self.hover_button = self.hit_test_button(point);
    }

    fn handle_panel_pointer_down(&mut self, point: GuiPoint) {
        self.pressed_button = self.hit_test_button(point);
    }

    fn handle_panel_pointer_up(&mut self, point: GuiPoint) -> Option<LobbyAction> {
        let pressed = self.pressed_button.take();
        let hit = self.hit_test_button(point);
        if pressed.is_some() && hit == pressed {
            match hit {
                Some(LobbyButton::Ready) => Some(LobbyAction::ToggleReady),
                Some(LobbyButton::Start) => Some(LobbyAction::StartGame),
                None => None,
            }
        } else {
            None
        }
    }

    fn pointer_left(&mut self) {
        self.hover_button = None;
        self.pressed_button = None;
        self.pointer = None;
    }

    fn register_peer(&mut self, client_id: ClientId, name: String, kind: ParticipantKind) {
        let mut ready = self
            .participants
            .get(&client_id)
            .map(|participant| participant.ready)
            .unwrap_or(matches!(kind, ParticipantKind::Observer));
        if matches!(kind, ParticipantKind::Observer) {
            ready = true;
        }
        self.participants
            .insert(client_id, LobbyParticipantState { name, ready, kind });
    }

    fn unregister_peer(&mut self, client_id: ClientId) {
        if client_id == self.local_client_id {
            return;
        }
        self.participants.remove(&client_id);
        if !self.is_host && client_id == 0 {
            self.participants
                .entry(0)
                .or_insert_with(|| LobbyParticipantState::new("Host", ParticipantKind::Player));
        }
    }

    fn toggle_local_ready(&mut self) -> bool {
        if let Some(participant) = self.participants.get_mut(&self.local_client_id) {
            participant.ready = !participant.ready;
            participant.ready
        } else {
            false
        }
    }

    fn local_ready(&self) -> bool {
        self.participants
            .get(&self.local_client_id)
            .map(|participant| participant.ready)
            .unwrap_or(false)
    }

    fn render_overlay(&mut self, surface: &mut Surface, assets: &FrontendAssets) {
        let width = surface.width() as f32;
        let height = surface.height() as f32;
        let layout = self.layout(width, height).clone();

        fill_gui_rect(surface, &layout.panel, Color::new(16, 28, 52, 232));
        draw_panel_outline(surface, &layout.panel, Color::new(28, 44, 72, 255));

        let font = assets.font_arc();
        let font_ref = font.as_ref();

        font_ref.draw_text(
            surface,
            layout.panel.origin.x + 20.0,
            layout.panel.origin.y + 32.0,
            "Network Lobby",
            28.0,
            Color::opaque(224, 232, 248),
        );

        let scenario_text = self
            .selected_title
            .as_deref()
            .unwrap_or("Select a scenario from the list");
        font_ref.draw_text(
            surface,
            layout.scenario_rect.origin.x,
            layout.scenario_rect.origin.y,
            scenario_text,
            20.0,
            Color::opaque(196, 208, 228),
        );

        let participants_title = "Participants";
        font_ref.draw_text(
            surface,
            layout.participants_rect.origin.x,
            layout.participants_rect.origin.y - 6.0,
            participants_title,
            22.0,
            Color::opaque(204, 214, 230),
        );

        let mut row_y = layout.participants_rect.origin.y + 20.0;
        let row_spacing = 8.0;
        let row_height = 26.0;
        let name_color = Color::opaque(220, 230, 248);
        let local_name_color = Color::opaque(236, 224, 180);
        let ready_color = Color::opaque(136, 220, 156);
        let waiting_color = Color::opaque(236, 148, 132);

        for (client_id, participant) in &self.participants {
            if row_y + row_height
                > layout.participants_rect.origin.y + layout.participants_rect.size.height
            {
                break;
            }

            let background = GuiRect::new(
                layout.participants_rect.origin.x,
                row_y - 18.0,
                layout.participants_rect.size.width,
                row_height + 8.0,
            );
            fill_gui_rect(surface, &background, Color::new(22, 36, 60, 180));

            let label_color = if *client_id == self.local_client_id {
                local_name_color
            } else {
                name_color
            };
            font_ref.draw_text(
                surface,
                layout.participants_rect.origin.x + 8.0,
                row_y,
                &participant.name,
                20.0,
                label_color,
            );

            let status_text = if participant.ready {
                "Ready"
            } else {
                "Waiting"
            };
            let status_color = if participant.ready {
                ready_color
            } else {
                waiting_color
            };

            let status_width = font_ref.measure_text(status_text, 18.0).width;
            let status_x = layout.participants_rect.origin.x + layout.participants_rect.size.width
                - status_width
                - 8.0;

            font_ref.draw_text(surface, status_x, row_y, status_text, 18.0, status_color);

            row_y += row_height + row_spacing;
        }

        self.draw_ready_button(surface, font_ref, &layout);
        if let Some(start) = layout.start_button {
            self.draw_start_button(surface, font_ref, start);
        }
    }

    fn handle_key(&mut self, key: KeyCode, state: ElementState) -> Option<LobbyAction> {
        if state != ElementState::Pressed {
            return None;
        }
        match key {
            KeyCode::Enter if self.is_host => Some(LobbyAction::StartGame),
            KeyCode::Space | KeyCode::Enter => Some(LobbyAction::ToggleReady),
            _ => None,
        }
    }

    fn pointer_position(&self) -> Option<GuiPoint> {
        self.pointer
    }

    fn draw_ready_button(
        &self,
        surface: &mut Surface,
        font: &dyn TextFont,
        layout: &NetworkLobbyLayout,
    ) {
        let base = if self.local_ready() {
            Color::new(28, 76, 58, 236)
        } else {
            Color::new(52, 72, 108, 226)
        };
        let mut color = base;
        if self.hover_button == Some(LobbyButton::Ready) {
            color = offset_color(color, 18);
        }
        if self.pressed_button == Some(LobbyButton::Ready) {
            color = offset_color(color, 32);
        }
        fill_gui_rect(surface, &layout.ready_button, color);
        draw_panel_outline(surface, &layout.ready_button, Color::new(16, 24, 40, 255));

        let label = if self.local_ready() {
            "Unready"
        } else {
            "Ready"
        };
        let size = 20.0;
        let metrics = font.measure_text(label, size);
        let text_x =
            layout.ready_button.origin.x + (layout.ready_button.size.width - metrics.width) * 0.5;
        let text_y = layout.ready_button.origin.y + 12.0;
        let text_color = Color::opaque(236, 240, 248);
        font.draw_text(surface, text_x, text_y, label, size, text_color);
    }

    fn draw_start_button(&self, surface: &mut Surface, font: &dyn TextFont, rect: GuiRect) {
        let enabled = self.selected_identifier.is_some();
        let mut color = if enabled {
            Color::new(32, 96, 72, 236)
        } else {
            Color::new(40, 48, 68, 200)
        };
        if enabled && self.hover_button == Some(LobbyButton::Start) {
            color = offset_color(color, 22);
        }
        if enabled && self.pressed_button == Some(LobbyButton::Start) {
            color = offset_color(color, 36);
        }
        fill_gui_rect(surface, &rect, color);
        draw_panel_outline(surface, &rect, Color::new(16, 24, 40, 255));

        let label = if enabled { "Start" } else { "Select Scenario" };
        let size = 20.0;
        let metrics = font.measure_text(label, size);
        let text_x = rect.origin.x + (rect.size.width - metrics.width) * 0.5;
        let text_y = rect.origin.y + 12.0;
        let text_color = if enabled {
            Color::opaque(230, 244, 236)
        } else {
            Color::opaque(200, 204, 214)
        };
        font.draw_text(surface, text_x, text_y, label, size, text_color);
    }

    fn hit_test_button(&self, point: GuiPoint) -> Option<LobbyButton> {
        let layout = self.layout.as_ref()?;
        if point_in_rect(point, &layout.ready_button) {
            return Some(LobbyButton::Ready);
        }
        if let Some(rect) = layout.start_button.as_ref() {
            if point_in_rect(point, rect) {
                return Some(LobbyButton::Start);
            }
        }
        None
    }
}

fn point_in_rect(point: GuiPoint, rect: &GuiRect) -> bool {
    point.x >= rect.origin.x
        && point.x <= rect.origin.x + rect.size.width
        && point.y >= rect.origin.y
        && point.y <= rect.origin.y + rect.size.height
}

fn fill_gui_rect(surface: &mut Surface, rect: &GuiRect, color: Color) {
    let x0 = rect.origin.x.floor().clamp(0.0, surface.width() as f32) as i32;
    let y0 = rect.origin.y.floor().clamp(0.0, surface.height() as f32) as i32;
    let x1 = (rect.origin.x + rect.size.width)
        .ceil()
        .clamp(0.0, surface.width() as f32) as i32;
    let y1 = (rect.origin.y + rect.size.height)
        .ceil()
        .clamp(0.0, surface.height() as f32) as i32;

    for y in y0..y1 {
        for x in x0..x1 {
            let _ = surface.set_pixel(x as u32, y as u32, color);
        }
    }
}

fn draw_panel_outline(surface: &mut Surface, rect: &GuiRect, color: Color) {
    let top = GuiRect::new(rect.origin.x, rect.origin.y, rect.size.width, 2.0);
    let bottom = GuiRect::new(
        rect.origin.x,
        rect.origin.y + rect.size.height - 2.0,
        rect.size.width,
        2.0,
    );
    let left = GuiRect::new(rect.origin.x, rect.origin.y, 2.0, rect.size.height);
    let right = GuiRect::new(
        rect.origin.x + rect.size.width - 2.0,
        rect.origin.y,
        2.0,
        rect.size.height,
    );
    fill_gui_rect(surface, &top, color);
    fill_gui_rect(surface, &bottom, color);
    fill_gui_rect(surface, &left, color);
    fill_gui_rect(surface, &right, color);
}

fn offset_color(color: Color, delta: i16) -> Color {
    let adjust = |channel: u8| -> u8 { (channel as i16 + delta).clamp(0, 255) as u8 };
    Color::new(adjust(color.r), adjust(color.g), adjust(color.b), color.a)
}

impl IngameMouseState {
    fn new(start: ViewportPointer) -> Self {
        Self {
            start,
            last: start,
            moved: false,
        }
    }

    fn update(&mut self, pointer: ViewportPointer) {
        self.last = pointer;
        if !self.moved {
            let dx = (self.last.world.x - self.start.world.x).abs();
            let dy = (self.last.world.y - self.start.world.y).abs();
            if dx >= MOUSE_DRAG_THRESHOLD || dy >= MOUSE_DRAG_THRESHOLD {
                self.moved = true;
            }
        }
    }

    fn delta(&self) -> FloatVector2 {
        FloatVector2::new(
            self.last.world.x - self.start.world.x,
            self.last.world.y - self.start.world.y,
        )
    }
}

impl MenuLayer {
    fn new(title: impl Into<String>, entries: Vec<FrontendScenario>) -> Self {
        Self {
            title: title.into(),
            entries,
            folder: None,
        }
    }

    fn for_folder(folder: FrontendScenario) -> Self {
        Self {
            title: folder.title.clone(),
            entries: folder.children.clone(),
            folder: Some(folder),
        }
    }
}

impl MenuState {
    fn new(menu: StartupMenu, entries: Vec<FrontendScenario>) -> Self {
        let visible_entries = entries.clone();
        Self {
            menu,
            pointer_position: None,
            stack: vec![MenuLayer::new("Scenarios", entries)],
            visible_entries,
            search_edit: SearchEditState::default(),
            applied_search_text: String::new(),
            scenario_list_scroll: 0,
            list_scroll_selection: None,
            selection_info_scroll: 0,
            scrollbar_interaction: None,
            definition_checkbox_enabled: false,
            definition_checkbox_checked: false,
            definition_checkbox_focused: false,
            dialog_focus: ScenselDialogFocus::List,
            include_back: true,
        }
    }

    /// Switches Back-row injection and rebuilds the visible entries.
    fn set_include_back(&mut self, include_back: bool) {
        if self.include_back != include_back {
            self.include_back = include_back;
            self.refresh_menu_entries();
        }
    }

    /// The scenario behind the menu's selected row, if any.
    fn selected_scenario(&self) -> Option<&FrontendScenario> {
        let offset = usize::from(self.include_back);
        let index = self.menu.selected_index()?.checked_sub(offset)?;
        self.visible_entries.get(index)
    }

    /// The folder whose contents are currently listed (None at root).
    fn current_folder(&self) -> Option<&FrontendScenario> {
        self.stack.last().and_then(|layer| layer.folder.as_ref())
    }

    /// The list caption: current folder name, or "Scenarios" at the root
    /// (C4StartupScenSelDlg::UpdateList, cpp:1527-1535).
    fn book_caption(&self) -> &str {
        self.current_folder()
            .map(|folder| folder.title.as_str())
            .unwrap_or("Scenarios")
    }

    fn pointer_position(&self) -> Option<GuiPoint> {
        self.pointer_position
    }

    fn set_pointer_position(&mut self, position: Option<GuiPoint>) {
        self.pointer_position = position;
    }

    fn current_entries(&self) -> &[FrontendScenario] {
        self.stack
            .last()
            .map(|layer| layer.entries.as_slice())
            .unwrap_or_default()
    }

    fn activation_path(&self, identifier: &str) -> Option<Vec<FrontendScenario>> {
        let mut path = self
            .stack
            .iter()
            .filter_map(|layer| layer.folder.clone())
            .collect::<Vec<_>>();
        path.extend(find_frontend_entry_path(self.current_entries(), identifier)?);
        Some(path)
    }

    fn require_supported_activation(
        &self,
        identifier: &str,
    ) -> std::result::Result<Option<ScenarioKind>, ClassicParityBoundary> {
        let Some(path) = self.activation_path(identifier) else {
            return Ok(None);
        };
        let mut checked_groups = HashSet::new();
        for entry in &path {
            for entry_path in entry.path.iter().chain(entry.source_paths.iter()) {
                // FolderMap is a SubFolder (*.c4f) feature. Start at a folder
                // entry itself or at a leaf scenario's parent, then walk only
                // a contiguous .c4f chain. An extensionless RegularFolder
                // breaks C4ScenarioListLoader's SubFolder ancestry. UI-path
                // entries and every merged source path are checked here.
                let mut group_path = if matches!(entry.kind, ScenarioKind::Folder) {
                    Some(entry_path.as_path())
                } else {
                    entry_path.parent()
                };
                while let Some(candidate) = group_path {
                    if !candidate
                        .extension()
                        .and_then(|extension| extension.to_str())
                        .is_some_and(|extension| extension.eq_ignore_ascii_case("c4f"))
                    {
                        break;
                    }
                    group_path = candidate.parent();
                    let group_path = candidate;
                    if !checked_groups.insert(scenario_root_key(group_path)) {
                        continue;
                    }
                    if let Some(marker) = folder_map_marker(group_path)? {
                        return Err(ClassicParityBoundary::FolderMap {
                            identifier: group_path
                                .file_name()
                                .map(|name| name.to_string_lossy().into_owned())
                                .unwrap_or_else(|| entry.identifier.clone()),
                            marker,
                        });
                    }
                }
            }
        }
        Ok(path.last().map(|entry| entry.kind))
    }

    fn visible_entries(&self) -> &[FrontendScenario] {
        &self.visible_entries
    }

    fn set_search_text(&mut self, text: impl Into<String>) {
        self.search_edit.set_text(text);
    }

    fn insert_search_text(&mut self, text: &str) {
        self.search_edit.insert_text(text);
    }

    fn search_text(&self) -> &str {
        self.search_edit.text()
    }

    fn set_search_focused(&mut self, focused: bool) {
        if focused {
            self.definition_checkbox_focused = false;
            self.dialog_focus = ScenselDialogFocus::Search;
            self.search_edit.focus();
        } else {
            self.search_edit.blur();
            if self.dialog_focus == ScenselDialogFocus::Search {
                self.dialog_focus = ScenselDialogFocus::List;
            }
        }
    }

    fn search_focused(&self) -> bool {
        self.search_edit.is_focused()
    }

    fn sync_definition_checkbox_to_selection(&mut self) {
        let (enabled, checked) = self
            .selected_scenario()
            .filter(|entry| matches!(entry.kind, ScenarioKind::Scenario))
            .map(|entry| {
                (
                    !entry.local_only.unwrap_or(false),
                    entry.allow_user_change.unwrap_or(false),
                )
            })
            .unwrap_or((false, false));
        self.definition_checkbox_enabled = enabled;
        self.definition_checkbox_checked = checked;
        if !enabled {
            self.definition_checkbox_focused = false;
            if self.dialog_focus == ScenselDialogFocus::Definitions {
                self.dialog_focus = ScenselDialogFocus::List;
            }
        }
    }

    fn toggle_definition_checkbox(&mut self) -> bool {
        if !self.definition_checkbox_enabled {
            return false;
        }
        self.definition_checkbox_checked = !self.definition_checkbox_checked;
        true
    }

    fn set_definition_checkbox_focused(&mut self, focused: bool) -> bool {
        let focused = focused && self.definition_checkbox_enabled;
        if self.definition_checkbox_focused == focused {
            return false;
        }
        self.definition_checkbox_focused = focused;
        if focused {
            self.search_edit.blur();
            self.dialog_focus = ScenselDialogFocus::Definitions;
        } else if self.dialog_focus == ScenselDialogFocus::Definitions {
            self.dialog_focus = ScenselDialogFocus::List;
        }
        true
    }

    fn set_dialog_focus(&mut self, focus: ScenselDialogFocus) {
        let focus = if focus == ScenselDialogFocus::Definitions
            && !self.definition_checkbox_enabled
        {
            ScenselDialogFocus::List
        } else {
            focus
        };
        self.dialog_focus = focus;
        if focus == ScenselDialogFocus::Search {
            self.search_edit.focus();
        } else {
            self.search_edit.blur();
        }
        self.definition_checkbox_focused = focus == ScenselDialogFocus::Definitions;
    }

    const fn dialog_focus(&self) -> ScenselDialogFocus {
        self.dialog_focus
    }

    fn scenario_list_scroll(&self) -> i32 {
        self.scenario_list_scroll
    }

    fn scenario_list_max_scroll(&self, viewport_height: i32, pitch: i32) -> i32 {
        let row_count = self.visible_entries.len() + usize::from(self.include_back);
        let content_height = i32::try_from(row_count)
            .unwrap_or(i32::MAX)
            .saturating_mul(pitch)
            .saturating_sub(i32::from(row_count > 0));
        content_height.saturating_sub(viewport_height).max(0)
    }

    fn scroll_scenario_list_by(
        &mut self,
        amount: i32,
        viewport_height: i32,
        pitch: i32,
    ) -> bool {
        let max_scroll = self.scenario_list_max_scroll(viewport_height, pitch);
        let next = self
            .scenario_list_scroll
            .saturating_add(amount)
            .clamp(0, max_scroll);
        if next == self.scenario_list_scroll {
            return false;
        }
        self.scenario_list_scroll = next;
        self.list_scroll_selection = Some(self.menu.selected_index());
        true
    }

    fn ensure_list_selection_visible(
        &mut self,
        viewport_height: i32,
        pitch: i32,
        item_height: i32,
    ) {
        let Some(selection) = self.menu.selected_index() else {
            self.scenario_list_scroll = self
                .scenario_list_scroll
                .min(self.scenario_list_max_scroll(viewport_height, pitch));
            return;
        };
        let row_y = i32::try_from(selection)
            .unwrap_or(i32::MAX)
            .saturating_mul(pitch);
        if self.scenario_list_scroll > row_y {
            self.scenario_list_scroll = row_y;
        } else if self.scenario_list_scroll.saturating_add(viewport_height)
            < row_y.saturating_add(item_height)
        {
            self.scenario_list_scroll = row_y
                .saturating_add(item_height)
                .saturating_sub(viewport_height);
        }
        self.scenario_list_scroll = self
            .scenario_list_scroll
            .clamp(0, self.scenario_list_max_scroll(viewport_height, pitch));
        self.list_scroll_selection = Some(self.menu.selected_index());
    }

    fn select_list_index(&mut self, index: usize) -> Vec<StartupMenuAction> {
        match self.menu.select_entry_by_index(index) {
            Ok(actions) => actions,
            Err(err) => {
                tracing::error!(error = %err, index, "failed to select scenario list row");
                Vec::new()
            }
        }
    }

    fn move_list_selection_clamped(&mut self, delta: isize) -> Vec<StartupMenuAction> {
        let count = self.visible_entries.len() + usize::from(self.include_back);
        if count == 0 {
            return Vec::new();
        }
        let current = self.menu.selected_index().unwrap_or_else(|| {
            if delta.is_negative() {
                count - 1
            } else {
                0
            }
        });
        let next = current.saturating_add_signed(delta).min(count - 1);
        if next == current && self.menu.selected_index().is_some() {
            return Vec::new();
        }
        self.select_list_index(next)
    }

    fn select_list_home(&mut self) -> Vec<StartupMenuAction> {
        if self.visible_entries.is_empty() && !self.include_back {
            Vec::new()
        } else {
            self.select_list_index(0)
        }
    }

    fn select_list_end(&mut self) -> Vec<StartupMenuAction> {
        let count = self.visible_entries.len() + usize::from(self.include_back);
        count
            .checked_sub(1)
            .map(|index| self.select_list_index(index))
            .unwrap_or_default()
    }

    fn page_list_selection(
        &mut self,
        direction: i32,
        viewport_height: i32,
        pitch: i32,
        item_height: i32,
    ) -> Vec<StartupMenuAction> {
        let count = self.visible_entries.len() + usize::from(self.include_back);
        let Some(current) = self.menu.selected_index().filter(|index| *index < count) else {
            return if direction < 0 {
                self.select_list_end()
            } else {
                self.select_list_home()
            };
        };
        let pitch = pitch.max(1);
        let viewport_height = viewport_height.max(1);
        let max_scroll = self.scenario_list_max_scroll(viewport_height, pitch);
        let target = if direction >= 0 {
            let last_fully_visible = |scroll: i32| {
                scroll
                    .saturating_add(viewport_height)
                    .saturating_sub(item_height)
                    .max(0)
                    / pitch
            };
            let mut target = last_fully_visible(self.scenario_list_scroll)
                .max(current as i32)
                .min(count.saturating_sub(1) as i32) as usize;
            if target <= current && current + 1 < count {
                self.scenario_list_scroll = self
                    .scenario_list_scroll
                    .saturating_add(viewport_height)
                    .min(max_scroll);
                target = last_fully_visible(self.scenario_list_scroll)
                    .max(current.saturating_add(1) as i32)
                    .min(count.saturating_sub(1) as i32) as usize;
            }
            target
        } else {
            let first_fully_visible = |scroll: i32| {
                scroll.saturating_add(pitch - 1).max(0) / pitch
            };
            let mut target = first_fully_visible(self.scenario_list_scroll)
                .max(0)
                .min(current as i32) as usize;
            if target >= current && current > 0 {
                self.scenario_list_scroll = self
                    .scenario_list_scroll
                    .saturating_sub(viewport_height)
                    .max(0);
                target = first_fully_visible(self.scenario_list_scroll)
                    .min(current.saturating_sub(1) as i32)
                    .max(0) as usize;
            }
            target
        };
        if target == current {
            return Vec::new();
        }
        let actions = self.select_list_index(target);
        self.list_scroll_selection = Some(self.menu.selected_index());
        actions
    }

    fn scroll_selection_info_by(
        &mut self,
        amount: i32,
        metrics: lc_frontend::startup_scensel::SelectionInfoScrollMetrics,
    ) -> bool {
        let next = metrics.clamp_offset(self.selection_info_scroll.saturating_add(amount));
        if next == self.selection_info_scroll {
            return false;
        }
        self.selection_info_scroll = next;
        true
    }

    /// Applies the edit buffer like `OnSearchBarEnter -> UpdateList`
    /// (C4StartupScenSelDlg.h:434-437), preserving the selected entry by
    /// identity when it still survives and otherwise selecting the first.
    fn submit_search(&mut self) -> Vec<StartupMenuAction> {
        let old_selection = self
            .selected_scenario()
            .map(|entry| entry.identifier.clone());
        self.applied_search_text = self.search_edit.text().to_string();
        self.refresh_menu_entries();
        let index = old_selection
            .as_deref()
            .and_then(|identifier| {
                self.visible_entries
                    .iter()
                    .position(|entry| entry.identifier == identifier)
            })
            .or_else(|| (!self.visible_entries.is_empty()).then_some(0));
        index
            .map(|index| index + usize::from(self.include_back))
            .map(|index| match self.menu.select_entry_by_index(index) {
                Ok(actions) => actions,
                Err(err) => {
                    tracing::error!(error = %err, "failed to select submitted scenario search result");
                    Vec::new()
                }
            })
            .unwrap_or_else(|| {
                self.sync_definition_checkbox_to_selection();
                Vec::new()
            })
    }

    fn clear_search(&mut self) {
        self.search_edit = SearchEditState::default();
        self.applied_search_text.clear();
    }

    fn menu(&mut self) -> &mut StartupMenu {
        &mut self.menu
    }

    fn enter_folder(&mut self, identifier: &str) {
        let Some(path) = find_frontend_folder_path(self.current_entries(), identifier) else {
            return;
        };
        // Recursive search can expose a deep descendant directly. Restore
        // every intermediate layer so Back still traverses one folder.
        self.stack
            .extend(path.into_iter().map(MenuLayer::for_folder));
        self.pointer_position = None;
        self.scenario_list_scroll = 0;
        self.selection_info_scroll = 0;
        self.scrollbar_interaction = None;
        self.definition_checkbox_focused = false;
        self.dialog_focus = ScenselDialogFocus::List;
        self.clear_search();
        self.refresh_menu_entries();
    }

    fn leave_folder(&mut self) {
        if self.stack.len() <= 1 {
            return;
        }
        self.stack.pop();
        self.pointer_position = None;
        self.scenario_list_scroll = 0;
        self.selection_info_scroll = 0;
        self.scrollbar_interaction = None;
        self.definition_checkbox_focused = false;
        self.dialog_focus = ScenselDialogFocus::List;
        self.clear_search();
        self.refresh_menu_entries();
    }

    fn refresh_menu_entries(&mut self) {
        let needle = self.applied_search_text.to_lowercase();
        self.visible_entries = if needle.is_empty() {
            self.current_entries().to_vec()
        } else {
            let mut matches = Vec::new();
            collect_frontend_search_matches(self.current_entries(), &needle, &mut matches);
            matches
        };
        let entries = build_menu_entries(&self.visible_entries, self.include_back);
        if let Err(err) = self.menu.set_entries(entries) {
            tracing::error!(error = %err, "failed to update startup menu entries");
        }
        self.list_scroll_selection = None;
    }

    fn label_path(&self) -> String {
        if self.stack.is_empty() {
            return String::new();
        }
        self.stack
            .iter()
            .map(|layer| layer.title.clone())
            .collect::<Vec<_>>()
            .join(" / ")
    }

    fn select_default_entry(&mut self) -> Vec<StartupMenuAction> {
        if self.current_entries().is_empty() {
            return Vec::new();
        }
        // The first real entry (past the Back row when present), mirroring
        // SelectFirstEntry (C4StartupScenSelDlg.cpp:1536-1537).
        let target_index = usize::from(self.include_back);
        match self.menu.select_entry_by_index(target_index) {
            Ok(actions) => actions,
            Err(err) => {
                tracing::error!(error = %err, "failed to select default scenario entry");
                Vec::new()
            }
        }
    }
}

fn collect_frontend_search_matches(
    entries: &[FrontendScenario],
    needle: &str,
    matches: &mut Vec<FrontendScenario>,
) {
    for entry in entries {
        let mut name = entry.title.clone();
        Markup::strip_markup(&mut name);
        if name.to_lowercase().contains(needle) {
            matches.push(entry.clone());
        }
        collect_frontend_search_matches(&entry.children, needle, matches);
    }
}

fn find_frontend_folder_path(
    entries: &[FrontendScenario],
    identifier: &str,
) -> Option<Vec<FrontendScenario>> {
    for entry in entries {
        if !matches!(entry.kind, ScenarioKind::Folder) {
            continue;
        }
        if entry.identifier == identifier {
            return Some(vec![entry.clone()]);
        }
        if let Some(mut descendants) = find_frontend_folder_path(&entry.children, identifier) {
            let mut path = Vec::with_capacity(descendants.len() + 1);
            path.push(entry.clone());
            path.append(&mut descendants);
            return Some(path);
        }
    }
    None
}

fn find_frontend_entry_path(
    entries: &[FrontendScenario],
    identifier: &str,
) -> Option<Vec<FrontendScenario>> {
    for entry in entries {
        if entry.identifier == identifier {
            return Some(vec![entry.clone()]);
        }
        if let Some(mut descendants) = find_frontend_entry_path(&entry.children, identifier) {
            let mut path = Vec::with_capacity(descendants.len() + 1);
            path.push(entry.clone());
            path.append(&mut descendants);
            return Some(path);
        }
    }
    None
}

fn folder_map_marker(path: &Path) -> std::result::Result<Option<PathBuf>, ClassicParityBoundary> {
    let group = open_group_path_for_folder_map(path).map_err(|error| {
        ClassicParityBoundary::FolderMapInspection {
            path: path.to_path_buf(),
            detail: error.to_string(),
        }
    })?;
    let entries = group
        .entries()
        .map_err(|error| ClassicParityBoundary::FolderMapInspection {
            path: path.to_path_buf(),
            detail: error.to_string(),
        })?;
    Ok(entries
        .into_iter()
        .find(|entry| {
            !entry.is_directory
                && entry
                    .relative_path
                    .file_name()
                    .and_then(|name| name.to_str())
                    .is_some_and(|name| name.eq_ignore_ascii_case("FolderMap.txt"))
        })
        .map(|entry| path.join(entry.relative_path)))
}

fn open_group_path_for_folder_map(path: &Path) -> std::result::Result<Group, GroupError> {
    if path.exists() {
        return Group::open(path);
    }

    // Packed child groups expose a logical `outer.c4f/inner.c4f` root even
    // though only `outer.c4f` exists in the filesystem. Reopen the nearest
    // real ancestor and traverse children through the group's
    // case-insensitive index instead of treating the logical path as a file.
    let mut ancestor = path.to_path_buf();
    let mut children = Vec::new();
    while !ancestor.exists() {
        let Some(name) = ancestor.file_name().map(|name| name.to_os_string()) else {
            return Err(GroupError::Missing(path.to_path_buf()));
        };
        children.push(PathBuf::from(name));
        if !ancestor.pop() {
            return Err(GroupError::Missing(path.to_path_buf()));
        }
    }
    let mut group = Group::open(&ancestor)?;
    for child in children.iter().rev() {
        group = open_child_flexible(&group, child)?
            .ok_or_else(|| GroupError::EntryNotFound(path.to_path_buf()))?;
    }
    Ok(group)
}

