    #[test]
    fn dragon_rock_selects_fantasy_music_never_princess_scream() {
        let repository = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root")
            .to_path_buf();
        let fantasy = repository.join("content/Fantasy.c4f");
        let scenario = fantasy.join("Drachenfels.c4s");
        if !scenario.exists() {
            return;
        }

        let selected = load_scenario_music_bytes(&scenario)
            .expect("inspect Dragon Rock music")
            .expect("Fantasy music track");
        let scream = fs::read(scenario.join("Princess.c4d/PrincessScream.wav"))
            .expect("read Princess scream");
        let music_group = fantasy.join("Music.c4g");
        let expected_tracks: Vec<_> = [
            "Knightly Wonders.mid",
            "Medieval Waltz.mid",
            "Morning Dawn.mid",
        ]
        .into_iter()
        .map(|name| fs::read(music_group.join(name)).expect("read Fantasy music"))
        .collect();

        assert_ne!(selected, scream, "sound effect was promoted to music");
        assert!(
            expected_tracks.contains(&selected),
            "Dragon Rock did not select from Fantasy.c4f/Music.c4g"
        );
    }

    #[test]
    fn menu_dump_writes_main_menu_png_at_1280x720() {
        lc_core::logging::init();

        let dir = tempdir().expect("tempdir");
        let repository = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(repository)),
            ("LC_USER_DATA_DIR", Some(dir.path())),
        ]);
        let app_paths = Arc::new(AppPaths::discover().expect("discover exact menu resources"));
        let path = dir.path().join("menu.png");
        run_menu_dump(
            &path,
            "main",
            Some(&app_paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("dump startup menu frame");

        // PNG IHDR: width/height are big-endian u32 at byte offsets 16/20.
        let png = fs::read(&path).expect("read dumped png");
        assert_eq!(&png[..8], b"\x89PNG\r\n\x1a\n", "not a PNG file");
        let width = u32::from_be_bytes(png[16..20].try_into().unwrap());
        let height = u32::from_be_bytes(png[20..24].try_into().unwrap());
        assert_eq!((width, height), (1280, 720));
    }

    #[test]
    fn missing_supplemental_scenario_asset_refuses_generic_fallback() {
        let mut app = new_classic_menu_app(320, 200);
        Arc::get_mut(&mut app.assets)
            .expect("frontend assets are app-owned")
            .startup_dialog_images
            .remove("GUIButtonDown.png")
            .expect("classic fixture includes the scenario button-down image");
        app.open_scenario_browser();
        let mut frame = vec![0x5a; 320 * 200 * 4];

        let error = app
            .render(&mut frame)
            .expect_err("generic scenario browser must be rejected");
        assert!(
            error.to_string().contains("refusing generic Rust fallback"),
            "unexpected error: {error:#}"
        );
        assert!(frame.iter().all(|byte| *byte == 0x5a));
    }

    #[test]
    fn menu_music_runs_in_menu_cycle() {
        lc_core::logging::init();

        // Music discovery reads process env; hold the env lock so the
        // EnvGuard-based tests cannot redirect paths mid-load.
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("isolated user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app with audio");

        // Menu music is started by `ensure_menu_music()` when asynchronous boot
        // loading completes and the menu is shown; pump boot to that point first.
        wait_for_menu(&mut app);

        // Music decodes on a worker thread now (the FluidSynth render must
        // never block the caller) — poll for playback start.
        let wait_for_music = |app: &GameApp| {
            let started = std::time::Instant::now();
            loop {
                let playing = app
                    .audio
                    .as_ref()
                    .map(|audio| audio.music_is_playing())
                    .unwrap_or(false);
                if playing || started.elapsed() > std::time::Duration::from_secs(20) {
                    break playing;
                }
                std::thread::sleep(std::time::Duration::from_millis(50));
            }
        };
        assert!(wait_for_music(&app), "menu music should start on launch");

        app.start_sandbox_scenario(FrontendScenario::fallback())
            .expect("start sandbox scenario");
        assert!(
            wait_for_music(&app),
            "sandbox scenario should have looping music"
        );

        app.return_to_menu();
        assert!(
            wait_for_music(&app),
            "menu music should resume after returning to the menu"
        );
    }

